    // simulate new Command
    when(commandSourceService.findCommandSource(any(), any())).thenReturn(null).thenReturn(// simulate stuck Command
    commandSource).thenReturn(// simulate stuck Command
    commandSource);
    when(commandSource.getStatus()).// on first hit we don't have a command source because it is new.
    // on 2nd hit we have a stuck one
    thenReturn(//
    CommandProcessingResultType.UNDER_PROCESSING.getValue()).thenReturn(//
    CommandProcessingResultType.UNDER_PROCESSING.getValue());
