    // Create an installment that is due
    LoanRepaymentScheduleInstallment installment = spy(new LoanRepaymentScheduleInstallment(loan, 1, disbursementDate, transactionDate, BigDecimal.valueOf(100L), BigDecimal.valueOf(0L), BigDecimal.valueOf(100L), BigDecimal.valueOf(0L), false, null, BigDecimal.ZERO));
    // Let's set up a credit transaction so that its transaction date coincides with the payment due date
    when(loanTransaction.getTransactionDate()).thenReturn(transactionDate);
