            return ByteBuffer.wrap("test_data_for_loan_adjust_transaction".getBytes(UTF_8));
        }

        @Override
        public String key() {
            return "test_key_1";
        }
    }, new ExternalEventCustomDataSerializer<>() {

        @Override
        public ByteBuffer serialize(final LoanAdjustTransactionBusinessEvent event) {
            return ByteBuffer.wrap("test_data_for_loan_adjust_transaction_1".getBytes(UTF_8));
        }

        @Override
        public String key() {
            return "test_key_1";
        }
    }, new ExternalEventCustomDataSerializer<>() {

        @Override
        public ByteBuffer serialize(final LoanAdjustTransactionBusinessEvent event) {
            return ByteBuffer.wrap("test_data_for_loan_adjust_transaction_2".getBytes(UTF_8));
        }

        @Override
        public String key() {
            return "test_key_2";
        }
    });
    LoanAdjustTransactionBusinessEventSerializer serializer = new LoanAdjustTransactionBusinessEventSerializer(service, new LoanTransactionDataMapperImpl(avroDateTimeMapper, externalIdMapper), loanChargePaidByReadService, externalEventCustomDataSerializers);
    LoanTransaction transactionToAdjust = Mockito.mock(LoanTransaction.class);
    LoanAdjustTransactionBusinessEvent.Data loanAdjustTransactionBusinessEventData = new LoanAdjustTransactionBusinessEvent.Data(transactionToAdjust);
    LocalDate reversedOnDate = LocalDate.now(ZoneId.systemDefault());
    String reversedLocalDate = reversedOnDate.format(DateTimeFormatter.ISO_DATE);
    LoanAdjustTransactionBusinessEvent businessEvent = new LoanAdjustTransactionBusinessEvent(loanAdjustTransactionBusinessEventData);
    LoanTransactionData transactionToAdjustData = LoanTransactionData.builder().id(1L).officeId(1L).officeName("").type(LoanEnumerations.transactionType(2)).date(LocalDate.now(ZoneId.systemDefault())).amount(BigDecimal.valueOf(0.0)).netDisbursalAmount(BigDecimal.valueOf(0.0)).principalPortion(BigDecimal.valueOf(0.0)).interestPortion(BigDecimal.valueOf(0.0)).feeChargesPortion(BigDecimal.valueOf(0.0)).penaltyChargesPortion(BigDecimal.valueOf(0.0)).overpaymentPortion(BigDecimal.valueOf(0.0)).unrecognizedIncomePortion(BigDecimal.valueOf(0.0)).externalId(new ExternalId("testExternalId")).outstandingLoanBalance(BigDecimal.valueOf(0.0)).submittedOnDate(LocalDate.now(ZoneId.systemDefault()).minusDays(4)).manuallyReversed(true).reversalExternalId(new ExternalId("testReversalExternalId")).reversedOnDate(reversedOnDate).loanId(1L).externalLoanId(new ExternalId("testExternalLoanId")).build();
    when(service.retrieveLoanTransaction(anyLong(), anyLong())).thenReturn(transactionToAdjustData);
    when(loanChargePaidByReadService.fetchLoanChargesPaidByDataTransactionId(anyLong())).thenReturn(new ArrayList<>());
    when(transactionToAdjust.getLoan()).thenReturn(loanForProcessing);
    when(loanForProcessing.getId()).thenReturn(1L);
